/**
 * Adds a visible, clickable URL below every card generated by rehype-og-card.
 */
export default function rehypeOGCardShowURL() {
  return (tree) => {
    visit(tree);
  };
}

function visit(node) {
  if (!Array.isArray(node.children)) {
    return;
  }

  for (let index = 0; index < node.children.length; index += 1) {
    const child = node.children[index];
    const classNames = child.properties?.className;

    if (
      child.type === "element" &&
      child.tagName === "div" &&
      Array.isArray(classNames) &&
      classNames.includes("og-card-container")
    ) {
      const cardLink = child.children.find(
        (candidate) =>
          candidate.type === "element" && candidate.tagName === "a",
      );
      const url = cardLink?.properties?.href;

      if (typeof url === "string") {
        node.children.splice(index + 1, 0, createURLParagraph(url));
        index += 1;
      }
    } else {
      visit(child);
    }
  }
}

function createURLParagraph(url) {
  return {
    type: "element",
    tagName: "p",
    properties: { className: ["og-card-source-url"] },
    children: [
      {
        type: "element",
        tagName: "a",
        properties: {
          href: url,
          rel: ["noopener", "noreferrer"],
          target: "_blank",
        },
        children: [{ type: "text", value: url }],
      },
    ],
  };
}
